const T=(s,f)=>{const d=new Uint8Array(s*s*4);f((x,y,r,g,b,a)=>{const o=(y*s+x)*4;d.set([r,g,b,a],o)});const t=new THREE.DataTexture(d,s,s,THREE.RGBAFormat);t.needsUpdate=true;t.wrapS=t.wrapT=THREE.RepeatWrapping;return t};
const S=(n,a)=>T(128,q=>{for(let y=0;y<128;y++)for(let x=0;x<128;x++){const p=y/128*n+Math.sin(x/128*9.4)*a;q(x,y,228,242,247,Math.round(Math.pow(.5+.5*Math.sin(p*6.28),2.6)*255))}});
const g=new THREE.PlaneGeometry(38,19,76,38),w=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:0x4f6a70,roughness:.16,metalness:.55}));
w.rotation.x=-Math.PI/2;w.position.set(0,.06,-1.2);const p=g.attributes.position,b=Array.from({length:p.count},(_,i)=>({x:p.getX(i),y:p.getY(i)}));
const A=t=>{for(let i=0;i<p.count;i++){const z=b[i],d=Math.hypot(z.x,z.y);p.setZ(i,Math.sin(z.x*.55+t*.9)*.075+Math.sin(z.y*.8-t*1.25)*.052+Math.sin(d*1.6-t*1.8)*.018)}p.needsUpdate=true;g.computeVertexNormals()};
const rt=new THREE.WebGLCubeRenderTarget(128),cc=new THREE.CubeCamera(.2,60,rt);w.material.envMap=rt.texture;
const L=(n,o)=>{const m=new THREE.Mesh(new THREE.PlaneGeometry(38,19),new THREE.MeshBasicMaterial({map:S(n,6),transparent:true,opacity:o,blending:THREE.AdditiveBlending}));m.material.map.repeat.set(n/8,2);m.rotation.x=-Math.PI/2;return m};
const r1=L(26,.32),r2=L(48,.2);
const F=(()=>{const s=128,d=new Uint8Array(s*s*4);for(let i=0;i<110;i++){const cx=Math.random()*s,cy=Math.random()*s,rad=.8+Math.random()*3.4;for(let y=Math.max(0,cy-rad|0);y<Math.min(s,cy+rad);y++)for(let x=Math.max(0,cx-rad|0);x<Math.min(s,cx+rad);x++){const q=Math.hypot(x-cx,y-cy);if(q<=rad){const o=(y*s+x)*4;d[o]=255;d[o+1]=255;d[o+2]=255;d[o+3]=Math.round((1-q/rad)*230)}}}const t=new THREE.DataTexture(d,s,s,THREE.RGBAFormat);t.needsUpdate=true;t.wrapS=t.wrapT=THREE.RepeatWrapping;return t})();
const fm=new THREE.MeshBasicMaterial({map:F,transparent:true,opacity:.85});const f1=new THREE.Mesh(new THREE.TorusGeometry(4.6,.22,4,40,Math.PI*.62),fm);f1.rotation.set(-Math.PI/2,0,1.75);f1.position.set(-5.4,.12,-1.6);scene.add(w,r1,r2,f1,cc);
